function obtenirLotDocumentPdfCDQV2268(id, revision, indexDebut, nombreChunks) {
  verifierDroit_('lecture');
  const f = obtenirPdfClientCDQ_(id).fichier;
  const revisionCourante = f.getLastUpdated().toISOString();
  const taille = Number(f.getSize());
  if (revisionCourante !== String(revision)) throw new Error('Le PDF a changé. Réessayez.');
  if (!taille || taille > CDQ_DOCUMENT_MAX_BYTES_) throw new Error('PDF trop volumineux.');

  const chunkSize = CDQ_DOCUMENT_CHUNK_BYTES_;
  const total = Math.ceil(taille / chunkSize);
  const start = Math.max(0, Math.floor(Number(indexDebut) || 0));
  const count = Math.max(1, Math.min(4, Math.floor(Number(nombreChunks) || 1)));
  if (start >= total) throw new Error('Lot PDF inexistant.');

  const endIndex = Math.min(total, start + count);
  const byteStart = start * chunkSize;
  const byteEnd = Math.min(taille - 1, endIndex * chunkSize - 1);

  const url = 'https://www.googleapis.com/drive/v3/files/' +
    encodeURIComponent(f.getId()) + '?alt=media&supportsAllDrives=true';
  const response = UrlFetchApp.fetch(url, {
    method:'get',
    headers:{
      Authorization:'Bearer ' + ScriptApp.getOAuthToken(),
      Range:'bytes=' + byteStart + '-' + byteEnd
    },
    muteHttpExceptions:true,
    followRedirects:true
  });

  const code = response.getResponseCode();
  let bytes = response.getContent();
  const attendu = byteEnd - byteStart + 1;

  if (code === 200 && bytes.length === taille) {
    bytes = bytes.slice(byteStart, byteEnd + 1);
  } else if (code !== 206 && code !== 200) {
    throw new Error('Lecture du PDF impossible (' + code + ').');
  }
  if (bytes.length !== attendu) throw new Error('Lot PDF incomplet.');

  const chunks = [];
  for (let index = start; index < endIndex; index++) {
    const localStart = (index - start) * chunkSize;
    const localEnd = Math.min(bytes.length, localStart + chunkSize);
    chunks.push({
      index:index,
      base64:Utilities.base64Encode(bytes.slice(localStart, localEnd))
    });
  }

  if (f.getLastUpdated().toISOString() !== String(revision))
    throw new Error('Le PDF a changé pendant la lecture.');

  return {
    revision:String(revision),
    taille:taille,
    chunkSize:chunkSize,
    total:total,
    chunks:chunks
  };
}
